    ListNode* head = nullptr;
    for (int i = (int) values.size() - 1; i >= 0; i--) {
        ListNode* node = new ListNode(values[i]);
        node->next = head;
        head = node;
    }
    if (pos >= 0) {
        ListNode* tail = head;
        while (tail->next != nullptr) tail = tail->next;
        ListNode* target = head;
        for (int i = 0; i < pos; i++) target = target->next;
        tail->next = target;
    }
    return head;
}

